echo '' | base64 -d > /tmp/reclaim_dry.sql
echo '' | base64 -d > /tmp/reclaim_apply.sql

echo '########## TEST 1: DRY-RUN (apply=off) ##########'
psql -U llm_gateway -d llm_gateway -v ON_ERROR_STOP=1 -f /tmp/reclaim_dry.sql 2>&1 | tail -45
echo "TEST1_PIPE_EXIT=$?"

echo ''
echo '########## TEST 2: REAL APPLY inside BEGIN, then ROLLBACK ##########'
{
  echo 'BEGIN;'
  cat /tmp/reclaim_apply.sql
  echo 'ROLLBACK;'
} > /tmp/reclaim_rehearse.sql
psql -U llm_gateway -d llm_gateway -v ON_ERROR_STOP=1 -f /tmp/reclaim_rehearse.sql 2>&1 | grep -Ev '^\(1 row\)|^$|^-+$|NOTICE' | tail -45
echo "TEST2_PIPE_EXIT=$?"

echo ''
echo '########## POST-ROLLBACK CHECK: bak_* count must be unchanged ##########'
psql -U llm_gateway -d llm_gateway -A -t -c "SELECT count(*)||' bak tables remain' FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname LIKE 'bak\_%';"
psql -U llm_gateway -d llm_gateway -A -t -c "SELECT 'usage_facts_default exists='||(to_regclass('public.usage_facts_default') IS NOT NULL)::text;"